import{_ as i,o as n,c as l,a2 as s,j as a,a as t}from"./chunks/framework.DxqK4cCD.js";const k=JSON.parse('{"title":"Toward Active Object Detection for UAVs in the Wild: A Large-Scale Dataset, Benchmark and Method","description":"通过构建大规模真实世界数据集和基于JEPA的世界模型，显著提升了无人机主动目标检测的泛化能力。","frontmatter":{"title":"Toward Active Object Detection for UAVs in the Wild: A Large-Scale Dataset, Benchmark and Method","description":"通过构建大规模真实世界数据集和基于JEPA的世界模型，显著提升了无人机主动目标检测的泛化能力。","date":"2026-07-13","arxivId":"2607.09078","domain":"计算机视觉 · 机器人","level":"基础","tags":["主动目标检测","无人机","世界模型","联合嵌入预测架构","深度强化学习"],"originalUrl":"https://arxiv.org/abs/2607.09078","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-07-13/2607.09078.md"},"headers":[],"relativePath":"papers/daily/2026-07-13/2607.09078.md","filePath":"papers/daily/2026-07-13/2607.09078.md","lastUpdated":1786541753000}'),r={name:"papers/daily/2026-07-13/2607.09078.md"};function o(h,e,p,d,c,g){return n(),l("div",null,[...e[0]||(e[0]=[s("",15),a("ul",null,[a("li",null,[a("strong",null,"ATRNet-LUDO数据集构建"),t("：采用多旋翼无人机搭载高分辨率相机，在40个不同场景（包括城市、乡村、森林、沙漠等）中，对10类车辆目标（如轿车、卡车、公交车等）进行多视角、多高度、多角度的拍摄。每张全景图像包含多个目标，并配有精确的边界框（Bounding Box）和类别标签。同时，从全景图中裁剪出121万张局部单目标切片，用于细粒度特征学习。数据集支持构建部分可观测马尔可夫决策过程（Partially Observable Markov Decision Process, POMDP）环境，模拟无人机智能体的交互过程。")]),a("li",null,[a("strong",null,"AOD-JEPA世界模型"),t("：核心思想是构建一个世界模型，该模型包含一个编码器（Encoder）和一个预测器（Predictor）。编码器将当前观测图像 $o_t$ 映射到潜在状态表示 $s_t$。预测器则基于当前状态 $s_t$ 和动作 $a_t$，预测未来状态 $s_{t+1}$ 的嵌入表示。训练目标是使预测的嵌入与真实未来状态的嵌入尽可能接近。这通过一个对比损失（Contrastive Loss）或均方误差（Mean Squared Error, MSE）损失来实现。公式可表示为：$\\mathcal{L}"),a("em",{"t+1":""},"{JEPA} = | \\text{Predictor}(\\text{Encoder}(o_t), a_t) - \\text{Encoder}(o"),t(") |^2$。")]),a("li",null,[a("strong",null,"AOD特定先验知识融合"),t("：论文将AOD领域的先验知识融入世界模型。例如，引入目标运动模型（如恒定速度模型）来约束状态预测，使得预测更符合物理规律。同时，设计遮挡感知的注意力机制（Occlusion-Aware Attention），让模型在预测时重点关注未被遮挡的区域，忽略被遮挡部分的干扰。这些先验知识以辅助损失（Auxiliary Loss）或网络结构约束的形式加入。")]),a("li",null,[a("strong",null,"深度强化学习策略优化"),t("：在训练好的世界模型基础上，使用深度Q网络（Deep Q-Network, DQN）或近端策略优化（Proximal Policy Optimization, PPO）等DRL算法来学习主动观测策略。智能体的动作空间包括：调整无人机高度、水平旋转、垂直俯仰、前进/后退等。奖励函数（Reward Function）设计为检测精度的提升（如mAP变化）与动作代价（如能耗、时间）的加权和。")]),a("li",null,[a("strong",null,"训练与推理流程"),t("：训练时，智能体与环境交互，收集轨迹数据。世界模型和策略网络交替训练：先固定策略，用轨迹数据训练世界模型；再固定世界模型，用世界模型生成的预测状态训练策略。推理时，智能体仅使用策略网络和编码器，无需世界模型，实现高效在线决策。")])],-1),s("",6),a("ol",null,[a("li",null,[a("p",null,[a("strong",null,"JEPA损失函数"),t("：用于训练世界模型，使预测的未来状态嵌入与真实未来状态嵌入尽可能一致。 $$\\mathcal{L}"),a("em",{"(o_t,":"","a_t,":"","o_{t+1":""},"{JEPA} = \\mathbb{E}"),t(") \\sim \\mathcal{D}} \\left[ | f_{\\text{pred}}(f_{\\text{enc}}(o_t), a_t) - f_{\\text{enc}}(o_{t+1}) |^2 \\right]$$ 其中，$f_{\\text{enc}}$ 是编码器，$f_{\\text{pred}}$ 是预测器，$\\mathcal{D}$ 是经验回放缓冲区。")])]),a("li",null,[a("p",null,[a("strong",null,"AOD先验知识辅助损失"),t("：例如，引入目标运动一致性约束。 $$\\mathcal{L}"),a("em",{"t+1":""},"{prior} = \\mathbb{E} \\left[ | \\text{MotionModel}(s_t, a_t) - s"),t(" |^2 \\right]$$ 其中，MotionModel是基于恒定速度假设的目标运动模型。")])]),a("li",null,[a("p",null,[a("strong",null,"总损失函数"),t("：世界模型的总损失是JEPA损失和先验损失的加权和。 $$\\mathcal{L}"),a("em",{JEPA:""},"{total} = \\mathcal{L}"),t(" + \\lambda \\mathcal{L}_{prior}$$ 其中，$\\lambda$ 是平衡超参数。")])])],-1),s("",7),a("p",null,[t("执行动作后，无人机获得新观测 $o_{t+1}$，其中轿车遮挡减少到20%。编码器提取 $s_{t+1} = [0.3, -0.4, 0.9, ..., 0.2]$。同时，预测器 $f_{\\text{pred}}$ 根据 $s_t$ 和 $a_t$ 预测 $s_{t+1}' = [0.28, -0.42, 0.88, ..., 0.18]$。计算JEPA损失：$\\mathcal{L}"),a("em",{"t+1":""},"{JEPA} = | s"),t("' - s_{t+1} |^2 = 0.015$。")],-1),a("p",null,[t("此外，先验知识模块根据恒定速度模型，假设轿车在0.5秒内移动了0.3米，预测其新位置应与观测一致。若不一致，则产生辅助损失 $\\mathcal{L}"),a("em",{total:""},"{prior} = 0.01$。总损失 $\\mathcal{L}"),t(" = 0.015 + 0.5 \\times 0.01 = 0.02$。")],-1),s("",25)])])}const u=i(r,[["render",o]]);export{k as __pageData,u as default};
